import {FAMILIES,LEVELS} from '../../ui/semantics.js';
import{esc,fmt}from'../../ui/format.js';import{TYPES,RELATIONS}from'../../core/model.js';import{DIAGRAMS}from'../../core/mbse.js';
const options=(a,v)=>a.map(([k,label])=>`<option value="${esc(k)}" ${k===v?'selected':''}>${esc(label)}</option>`).join('');
export function diagramsView({m,d,zoom,selected,connectMode,connectFrom,connectionType,canvas,inspector,colorMode='family',focusSelection=false}){return `<section class="page-intro compact"><div><div class="eyebrow">CONSTRUIEȘTE · CONECTEAZĂ · ANALIZEAZĂ</div><h1>Diagrame & fluxuri</h1></div><button data-action="new-diagram">+ Diagramă nouă</button></section><div class="diagram-tabs" role="tablist" aria-label="Diagrame">${m.diagrams.map(x=>`<button role="tab" aria-selected="${x.id===d.id}" class="${x.id===d.id?'primary':''}" data-diagram="${esc(x.id)}">${esc(x.name)}</button>`).join('')}</div><div class="diagram-toolbar"><div class="mode-switch"><button data-action="select-mode" aria-pressed="${!connectMode}" class="${!connectMode?'selected-tool':''}">↖ Selectare</button><button data-action="connect-mode" aria-pressed="${connectMode}" class="${connectMode?'selected-tool':''}">↗ Conectare</button></div><label>Conexiune<select id="relation-type" aria-label="Conexiune">${options(DIAGRAMS[d.kind].relations.map(k=>[k,RELATIONS[k]]),connectionType)}</select></label><label>Culori<select id="diagram-colors" aria-label="Colorează diagrama"><option value="family" ${colorMode==='family'?'selected':''}>Familii de obiecte</option><option value="moflt" ${colorMode==='moflt'?'selected':''}>Nivel MOFLT</option></select></label><label class="focus-toggle"><input type="checkbox" id="focus-selection" ${focusSelection?'checked':''}>Izolează vecinii selecției</label><button data-action="fit">Încadrează</button><div class="zoom-control"><button data-action="zoom-out" aria-label="Micșorează">−</button><span>${fmt(zoom*100,0)}%</span><button data-action="zoom-in" aria-label="Mărește">+</button></div><details class="project-menu"><summary>Mai multe ▾</summary><div><button data-action="rename-diagram">Proprietăți diagramă</button><button data-action="layout">Aranjare automată</button><button data-action="svg">Export SVG</button><button data-action="delete-diagram">Șterge vederea</button></div></details></div><details class="diagram-legend"><summary>Legendă · ${colorMode==='moflt'?'niveluri MOFLT':'familii de obiecte'}</summary><div class="legend-items">${Object.values(colorMode==='moflt'?LEVELS:FAMILIES).map(t=>`<span><i style="background:${t.color}"></i>${esc(t.label)}</span>`).join('')}</div><p>Linie continuă: flux · întreruptă: date / dependență · punctată: alocare de resurse. Culorile obiectelor indică tipul sau nivelul, nu starea. Verde: valid · portocaliu: avertizare · roșu: eroare.</p></details><div class="diagram-layout"><aside class="palette"><h3>Adaugă în model</h3><button class="primary" data-page="library">▤ Bibliotecă</button><div class="palette-shortcuts">${DIAGRAMS[d.kind].types.slice(0,8).map(type=>`<button data-quick-node="${type}"><span>＋</span>${esc(TYPES[type])}</button>`).join('')}</div><details><summary>Toate tipurile</summary><select id="new-type" aria-label="Tip de element">${options(Object.entries(TYPES),DIAGRAMS[d.kind].types[0])}</select><button data-action="new-node">Creează element</button></details><button data-action="existing">Element existent</button><hr><p class="small">${esc(DIAGRAMS[d.kind].name)}</p><p class="small muted">${d.kind==='process'?'Fluxurile și alocările alimentează simularea.':'Vedere MBSE descriptivă a modelului comun.'}</p></aside><div class="canvas-frame ${connectMode?'connection-mode':''}"><div class="canvas-status" role="status">${connectMode?connectFrom?`② Alege destinația pentru ${esc(m.nodes.find(n=>n.id===connectFrom)?.name)} · Esc anulează`:'① Alege obiectul sursă, apoi destinația':'Trage obiectele pentru poziționare. Apasă + pe un obiect pentru a începe o conexiune.'}</div><div class="canvas-scroll">${d.items.length?'':`<div class="canvas-empty"><h2>Prima conexiune începe aici.</h2><p>Adaugă un utilaj din bibliotecă sau creează un obiect din paletă.</p><button data-page="library">Deschide biblioteca →</button></div>`}${canvas}</div><div class="canvas-footer">${d.items.length} obiecte în vedere · ${m.nodes.length} în model · Click pe o legătură pentru editare · Conexiunile sunt partajate între vederi</div></div><aside class="inspector" aria-label="Proprietăți selecție">${inspector}</aside></div>`}
